let projects=[];const grid=document.querySelector('#projects');const dialog=document.querySelector('#project-dialog');let lastTrigger;function showProject(p,trigger){lastTrigger=trigger;document.querySelector('#dialog-category').textContent=p.category;document.querySelector('#dialog-title').textContent=p.name;document.querySelector('#dialog-body').textContent=p.detail;const stack=document.querySelector('#dialog-stack');stack.replaceChildren(...p.stack.map(t=>{const s=document.createElement('span');s.textContent=t;return s}));const link=document.querySelector('#dialog-link');link.replaceChildren();if(p.repo&&/^https:\/\/github\.com\//.test(p.repo)){const a=document.createElement('a');a.href=p.repo;a.textContent='View repository ↗';link.append(a)}else{link.textContent='Public repository and demo links will be added when available.'}dialog.showModal()}function render(filter='All'){grid.replaceChildren();const visible=projects.filter(p=>filter==='All'||p.category===filter);visible.forEach((p,i)=>{const article=document.createElement('article');article.className='project';const visual=document.createElement('div');visual.className='project-visual';visual.setAttribute('aria-hidden','true');const num=document.createElement('span');num.className='project-number';num.textContent=String(projects.indexOf(p)+1).padStart(2,'0')+' / '+p.category.toUpperCase();const ring=document.createElement('div');ring.className='visual-ring';const word=document.createElement('span');word.className='visual-word';word.textContent=p.visualWord||['retrieve.','review.','remember.','estimate.','predict.'][projects.indexOf(p)]||'explore.';if(p.image){visual.removeAttribute('aria-hidden');const img=document.createElement('img');img.src=p.image;img.alt=p.imageAlt||p.name;img.loading='lazy';visual.append(img)}else{visual.append(num,ring,word)};const cat=document.createElement('span');cat.className='project-category';cat.textContent=p.category+(p.status?' · '+p.status:'');const info=document.createElement('div');info.className='project-info';const title=document.createElement('h3');title.textContent=p.name;const button=document.createElement('button');button.textContent='↗';button.setAttribute('aria-label','Read about '+p.name);button.addEventListener('click',()=>showProject(p,button));info.append(title,button);const desc=document.createElement('p');desc.textContent=p.description;const tags=document.createElement('div');tags.className='tags';p.stack.forEach(t=>{const s=document.createElement('span');s.textContent=t;tags.append(s)});article.append(visual,cat,info,desc,tags);grid.append(article)});document.querySelector('#project-status').textContent=visible.length+' projects shown';document.dispatchEvent(new Event('projects-rendered'))}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render(b.dataset.filter)}));document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>lastTrigger?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});fetch('projects.json?v=resume-aligned-20261020', {cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Project data unavailable');return r.json()}).then(data=>{projects=data.filter(p=>p.featured===true);render()}).catch(()=>{grid.textContent='Project details are temporarily unavailable. You can still explore my experience below or visit GitHub.'});